const CH="qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const GEN=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];
function polymod(v){let c=1;for(const d of v){const b=c>>>25;c=((c&0x1ffffff)<<5)^d;for(let i=0;i<5;i++)if((b>>>i)&1)c^=GEN[i];}return c>>>0;}
function hrpExp(h){const a=[],b=[];for(const ch of h){a.push(ch.codePointAt(0)>>>5);b.push(ch.codePointAt(0)&31);}return a.concat([0],b);}
function cksum(h,d){const v=hrpExp(h).concat(d,[0,0,0,0,0,0]);const m=polymod(v)^1;const r=[];for(let i=0;i<6;i++)r.push((m>>>(5*(5-i)))&31);return r;}
function conv(data,from,to,pad){let acc=0,bits=0;const ret=[];const maxv=(1<<to)-1,ma=(1<<(from+to-1))-1;
 for(const v of data){if(v<0||(v>>from))return null;acc=((acc<<from)|v)&ma;bits+=from;while(bits>=to){bits-=to;ret.push((acc>>bits)&maxv);}}
 if(pad){if(bits)ret.push((acc<<(to-bits))&maxv);}else if(bits>=from||((acc<<(to-bits))&maxv))return null;
 return ret;}
export function encodeRaw(hrp,data){return hrp+"1"+data.concat(cksum(hrp,data)).map(v=>CH[v]).join("");}
export function segwitEncode(hrp,ver,prog){const d=[ver].concat(conv(prog,8,5,true));return encodeRaw(hrp,d);}
export {conv,CH,polymod};
EOF
