import { segwitEncode, encodeRaw } from './enc.mjs';
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test5_executable';
function run(a, b) {
  try {
    return execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8' }).replace(/\n$/, '');
  } catch (e) {
    return 'RC' + e.status;
  }
}

const prog = Array.from({ length: 20 }, (_, i) => i);

console.log('--- total length bound ---');
for (const hlen of [49, 50, 51]) {
  const hrp = 'a'.repeat(hlen);
  const addr = segwitEncode(hrp, 1, prog);
  console.log('  totalLen=' + addr.length, '=>', run(hrp, addr));
}

console.log('--- separator search (rfind vs find) ---');
const a1 = segwitEncode('a1b', 0, prog);
console.log('  hrp "a1b" addr:', a1);
console.log('    --a a1b ->', run('a1b', a1), '| --a a ->', run('a', a1));
const emptyHrp = encodeRaw('', [0].concat(Array.from({ length: 32 }, () => 0)));
console.log('  empty hrp addr:', emptyHrp, '-> --a "" :', run('', emptyHrp));

console.log('--- case handling ---');
const base = segwitEncode('bc', 0, prog);
console.log('  base            :', base, '->', run('bc', base));
console.log('  ALLUPPER --a bc :', run('bc', base.toUpperCase()));
console.log('  ALLUPPER --a BC :', run('BC', base.toUpperCase()));
console.log('  hrpUP+dataLOW   :', run('bc', 'BC' + base.slice(2)));
console.log('  hrpLOW+dataUP   :', run('bc', 'bc' + base.slice(2).toUpperCase()));

console.log('--- char range [33,126] ---');
const specials = [
  ['space', ' '], ['tab', '\t'], ['nl', '\n'], ['cr', '\r'],
  ['DEL(0x7f)', String.fromCharCode(0x7f)], ['0x1f', String.fromCharCode(0x1f)],
  ['eacute', 'é'], ['omega', 'Ω'], ['emoji', '\u{1F600}'],
  ['dotless-i', 'ı'], ['kelvin', 'K'], ['long-s', 'ſ'],
];
for (const [n, ch] of specials) {
  console.log('  prefix ' + n.padEnd(10), '->', JSON.stringify(run('bc', ch + base)));
}

console.log('--- padding rules (pad=false rejection) ---');
// v1 with 20-byte program -> 32 data values, 160 bits, exact. Append data chars to create leftovers.
function rawFor(extra) {
  const d = [1].concat(Array.from({ length: 32 }, (_, i) => (i * 3) % 32)).concat(extra);
  return encodeRaw('bc', d);
}
console.log('  exact (no leftover)      :', run('bc', rawFor([])));
console.log('  +1 char, nonzero bits    :', run('bc', rawFor([31])));
console.log('  +1 char, zero bits       :', run('bc', rawFor([0])));
console.log('  +2 chars zero (10 bits)  :', run('bc', rawFor([0, 0])));

console.log('--- structural edges ---');
for (const s of ['', '1', '11', '1' + base, base + '1', 'bc1', 'bc1q', 'bc1qqqqq', 'bc1qqqqqq', 'q'.repeat(90)]) {
  console.log('  ' + JSON.stringify(s).padEnd(24), '->', run('bc', s));
}

