import { segwitEncode, encodeRaw } from './enc.mjs';
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test5_executable';
function run(a, b) {
  try {
    return execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8' }).replace(/\n$/, '');
  } catch (e) {
    return 'RC' + e.status;
  }
}
const prog = Array.from({ length: 20 }, (_, i) => i);

console.log('--- is there ANY max total length? ---');
for (const hlen of [1, 20, 48, 49, 50, 51, 52, 60, 83, 84, 85, 100, 200, 1000, 5000]) {
  const hrp = 'a'.repeat(hlen);
  const addr = segwitEncode(hrp, 1, prog);
  const r = run(hrp, addr);
  console.log('  hrpLen=' + String(hlen).padEnd(5), 'totalLen=' + String(addr.length).padEnd(6), '=>', r === '(None, None)' ? 'REJECT' : 'ACCEPT');
}

console.log('--- very long program (data) part, ver 1, len 40 vs 41 ---');
for (const L of [40, 41]) {
  const p = Array.from({ length: L }, (_, i) => i & 255);
  const addr = segwitEncode('bc', 1, p);
  console.log('  L=' + L, 'totalLen=' + addr.length, '=>', run('bc', addr) === '(None, None)' ? 'REJECT' : 'ACCEPT');
}

console.log('--- hrp char range: which HRP chars are allowed? ---');
// build addr with hrp containing a specific char; only [33,126] should pass the range check
for (const code of [33, 45, 47, 48, 57, 58, 64, 65, 90, 91, 95, 96, 97, 122, 123, 126]) {
  const ch = String.fromCharCode(code);
  const hrp = 'x' + ch + 'z';
  const addr = segwitEncode(hrp, 0, prog);
  const r = run(hrp, addr);
  console.log('  hrp "x' + ch + 'z" (0x' + code.toString(16) + ')', '=>', r === '(None, None)' ? 'REJECT' : 'ACCEPT');
}

console.log('--- uppercase char in hrp makes it mixed-case ---');
{
  const addr = segwitEncode('xXz', 0, prog);
  console.log('  hrp "xXz" as-encoded:', addr, '=>', run('xXz', addr) === '(None, None)' ? 'REJECT' : 'ACCEPT');
  console.log('  same, fully uppercased, --a xxz:', run('xxz', addr.toUpperCase()) === '(None, None)' ? 'REJECT' : 'ACCEPT');
}

console.log('--- byte values 0..255 render as plain ints (list not bytes)? ---');
{
  const p = [0, 9, 10, 13, 34, 39, 92, 127, 255, 128, 1, 2, 3, 4, 5, 6, 7, 8, 254, 253];
  const addr = segwitEncode('bc', 0, p);
  console.log('  addr:', addr);
  console.log('  out :', run('bc', addr));
}

console.log('--- witver 1..16 success rendering ---');
for (const v of [1, 2, 16]) {
  const addr = segwitEncode('bc', v, [1, 2]);
  console.log('  v' + v + ':', run('bc', addr));
}

