import { segwitEncode, encodeRaw } from './enc.mjs';
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test5_executable';
function ok(a, b) {
  try {
    return execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8' }).replace(/\n$/, '') !== '(None, None)';
  } catch (e) { return 'RC' + e.status; }
}

// For each program byte length (=> data-part length), binary-search the max hrp length that still decodes.
console.log('progLen dataChars  maxHrpLen  total(maxHrp)  hrp+1+data');
for (const L of [2, 10, 20, 32, 40]) {
  const p = Array.from({ length: L }, (_, i) => i & 255);
  const dataChars = segwitEncode('x', 1, p).length - 2; // minus hrp(1) and '1'
  let lo = 1, hi = 300;
  // find boundary
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    const hrp = 'a'.repeat(mid);
    if (ok(hrp, segwitEncode(hrp, 1, p))) lo = mid; else hi = mid - 1;
  }
  const total = lo + 1 + dataChars;
  console.log(String(L).padStart(6), String(dataChars).padStart(9), String(lo).padStart(10), String(total).padStart(14), '  ' + lo + '+1+' + dataChars);
}

console.log('\n--- confirm monotonic (no holes) around each boundary for progLen 20 ---');
{
  const p = Array.from({ length: 20 }, (_, i) => i);
  for (let h = 80; h <= 88; h++) {
    const hrp = 'a'.repeat(h);
    const addr = segwitEncode(hrp, 1, p);
    console.log('  hrpLen=' + h, 'total=' + addr.length, ok(hrp, addr) ? 'ACCEPT' : 'REJECT');
  }
}

console.log('\n--- raw (non-segwit) data lengths: vary data part with fixed short hrp ---');
{
  for (const n of [1, 2, 6, 7, 20, 50, 60, 70, 80, 82, 83, 84, 85, 90, 120]) {
    const d = [1].concat(Array.from({ length: n }, (_, i) => i % 32));
    const addr = encodeRaw('bc', d);
    console.log('  dataVals=' + String(n + 1).padStart(4), 'total=' + String(addr.length).padStart(4), ok('bc', addr) ? 'ACCEPT' : 'REJECT');
  }
}

