import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test5_executable';

function run(argv) {
  const r = { out: '', err: '', rc: 0 };
  try {
    r.out = execFileSync(EXE, argv, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) {
    r.rc = e.status; r.out = e.stdout || ''; r.err = e.stderr || '';
  }
  return r;
}
const show = (argv) => {
