/**
 * Bech32 alphabet, BCH generator coefficients and the per-character helpers
 * shared by the checksum and string-decoding layers.
 */

/** The 32 data characters. The index of a character *is* its 5-bit value. */
export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

/** Generator coefficients of the BCH code that backs the bech32 checksum. */
export const GENERATOR = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

/** Value the polymod of a checksum-valid bech32 string reduces to. */
export const BECH32_CONST = 1;

/** Number of trailing data characters that carry the checksum. */
export const CHECKSUM_LENGTH = 6;

/**
 * Longest human-readable part the decoder accepts. Established by probing the
 * reference program: an 83-character HRP decodes, an 84-character one does not,
 * and the bound is independent of the length of the data part (a 155-character
 * address with an 83-character HRP still decodes).
 */
export const MAX_HRP_LENGTH = 83;

const VALUE_BY_CHAR = new Map();
for (let index = 0; index < CHARSET.length; index += 1) {
  VALUE_BY_CHAR.set(CHARSET[index], index);
}

/** Mirrors `CHARSET.find(ch)`: the 5-bit value of `ch`, or -1 when absent. */
export function charsetValue(ch) {
  const value = VALUE_BY_CHAR.get(ch);
  return value === undefined ? -1 : value;
}

/**
 * Mirrors `33 <= ord(ch) <= 126`. `ch` is a single Unicode code point, so
 * astral characters are rejected as a whole rather than per surrogate half.
 */
export function isPrintableAsciiChar(ch) {
  const code = ch.codePointAt(0);
  return code >= 33 && code <= 126;
}

