/**
 * The bech32 checksum: the BCH polymod, the human-readable-part expansion and
 * the create/verify pair built on top of them.
 */

import { BECH32_CONST, CHECKSUM_LENGTH, GENERATOR } from './charset.mjs';

/**
 * Reduce a sequence of 5-bit values with the bech32 generator polynomial.
 *
 * The accumulator never exceeds 30 bits: `(chk & 0x1ffffff) << 5` peaks at
 * 0x3fffffe0, comfortably below the sign bit, so plain 32-bit operators agree
 * with Python's arbitrary-precision integers. `>>> 0` keeps every intermediate
 * unsigned so the final comparison against BECH32_CONST cannot see a negative.
 */
export function bech32Polymod(values) {
  let chk = 1;
  for (const value of values) {
    const top = chk >>> 25;
    chk = (((chk & 0x1ffffff) << 5) ^ value) >>> 0;
    for (let i = 0; i < 5; i += 1) {
      if ((top >>> i) & 1) chk = (chk ^ GENERATOR[i]) >>> 0;
    }
  }
  return chk >>> 0;
}

/** Expand the HRP into high bits, a zero separator, then low bits. */
export function bech32HrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const ch of hrp) {
    const code = ch.codePointAt(0);
    high.push(code >>> 5);
    low.push(code & 31);
  }
  return high.concat([0], low);
}

/** True when `data` (payload plus its 6 checksum values) checks out for `hrp`. */
export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod(bech32HrpExpand(hrp).concat(data)) === BECH32_CONST;
}

/** The 6 checksum values for `hrp` and a payload of 5-bit `data` values. */
export function bech32CreateChecksum(hrp, data) {
  const padding = new Array(CHECKSUM_LENGTH).fill(0);
  const polymod = (bech32Polymod(bech32HrpExpand(hrp).concat(data, padding)) ^ BECH32_CONST) >>> 0;
  const checksum = [];
  for (let i = 0; i < CHECKSUM_LENGTH; i += 1) {
    checksum.push((polymod >>> (5 * (5 - i))) & 31);
  }
  return checksum;
}

