/**
 * General base conversion between bit groups, used to move between the 5-bit
 * bech32 data values and the 8-bit witness program.
 */

/**
 * Regroup `data` from `fromBits`-wide values to `toBits`-wide values.
 *
 * Returns `null` (Python's `None`) when a value is out of range, or when
 * `pad` is false and the leftover bits cannot be dropped losslessly — that is,
 * when a whole `fromBits`-wide group is left over, or when the remaining bits
 * are not all zero.
 */
export function convertBits(data, fromBits, toBits, pad = true) {
  let acc = 0;
  let bits = 0;
  const result = [];
  const maxValue = (1 << toBits) - 1;
  const maxAcc = (1 << (fromBits + toBits - 1)) - 1;

  for (const value of data) {
    if (value < 0 || value >> fromBits) return null;
    acc = ((acc << fromBits) | value) & maxAcc;
    bits += fromBits;
    while (bits >= toBits) {
      bits -= toBits;
      result.push((acc >> bits) & maxValue);
    }
  }

  if (pad) {
    if (bits) result.push((acc << (toBits - bits)) & maxValue);
  } else if (bits >= fromBits || ((acc << (toBits - bits)) & maxValue)) {
    return null;
  }
  return result;
}

