import { bech32CreateChecksum, bech32VerifyChecksum } from './polymod.mjs';

/** Mirrors `any(ord(x) < 33 or ord(x) > 126 for x in bech)`, inverted. */
function isAllPrintableAscii(bech) {
  for (const ch of bech) {
    if (!isPrintableAsciiChar(ch)) return false;
