import { bech32Decode, bech32Encode } from './bech32.mjs';
import { convertBits } from './convertbits.mjs';

/** Inclusive bounds on the witness program length, in bytes. */
const MIN_PROGRAM_LENGTH = 2;
const MAX_PROGRAM_LENGTH = 40;

/** Highest witness version the decoder accepts. */
const MAX_WITNESS_VERSION = 16;

/** Witness version 0 only allows these two program lengths (P2WPKH / P2WSH). */
const V0_PROGRAM_LENGTHS = [20, 32];

/**
 * Decode a segwit address, returning `[witnessVersion, witnessProgram]` or
 * `[null, null]`.
 *
 * The guards are ordered exactly as in the Python original. That ordering
 * matters: the length check on the converted program runs *before* `data[0]`
 * is read, so an address whose payload is empty (HRP plus separator plus just
 * the six checksum characters) is rejected rather than raising an index error.
 */
export function decode(hrp, addr) {
  const [decodedHrp, data] = bech32Decode(addr);
  if (decodedHrp !== hrp) return [null, null];

  const program = convertBits(data.slice(1), 5, 8, false);
  if (
    program === null ||
    program.length < MIN_PROGRAM_LENGTH ||
    program.length > MAX_PROGRAM_LENGTH
  ) {
    return [null, null];
  }
  if (data[0] > MAX_WITNESS_VERSION) return [null, null];
  if (data[0] === 0 && !V0_PROGRAM_LENGTHS.includes(program.length)) return [null, null];

  return [data[0], program];
