export function encode(hrp, witnessVersion, witnessProgram) {
  const converted = convertBits(witnessProgram, 8, 5, true);
  if (converted === null) return null;
  const address = bech32Encode(hrp, [witnessVersion].concat(converted));
  const [checkHrp] = decode(hrp, address);
  return checkHrp === null ? null : address;
}

