/**
 * Rendering values the way Python's `print`/`repr` would, so stdout matches the
 * original byte for byte.
 */

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

function escapeCodePoint(ch) {
  const code = ch.codePointAt(0);
  if (code <= 0xff) return `\\x${code.toString(16).padStart(2, '0')}`;
  if (code <= 0xffff) return `\\u${code.toString(16).padStart(4, '0')}`;
  return `\\U${code.toString(16).padStart(8, '0')}`;
}

/**
 * `repr()` of a string: single quotes, switching to double quotes when the
 * value contains a single quote but no double quote, with C0/C1 controls and
 * DEL escaped.
 */
export function pythonRepr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let body = '';
  for (const ch of value) {
    const code = ch.codePointAt(0);
    if (SHORT_ESCAPES.has(ch)) body += SHORT_ESCAPES.get(ch);
    else if (ch === quote) body += `\\${ch}`;
    else if (code < 0x20 || code === 0x7f || (code >= 0x80 && code <= 0x9f)) body += escapeCodePoint(ch);
    else body += ch;
  }
  return `${quote}${body}${quote}`;
}

/**
 * `print(result)` of the 2-tuple returned by `bech32.decode`: either the
 * `(None, None)` failure sentinel or the witness version alongside the witness
 * program rendered as a Python list of integers.
 */
export function formatDecodeResult(result) {
  const [witnessVersion, witnessProgram] = result;
  if (witnessVersion === null) return '(None, None)';
  return `(${witnessVersion}, [${witnessProgram.join(', ')}])`;
}

