/**
 * A behaviour-faithful re-implementation of the slice of CPython's `argparse`
 * that this program exercises: `-h/--help` plus a set of required long options
 * that each take exactly one value.
 *
 * Structure mirrors the original (`_parse_optional`, `_get_option_tuples`,
 * `_parse_known_args`, `consume_optional`) so the observable corner cases —
 * prefix abbreviation, `=`-attached values, negative-number-looking values,
 * the `--` separator, and the precedence of "required" over "unrecognized" —
 * fall out rather than being special-cased.
 */

import { pythonRepr } from './pyformat.mjs';

const PREFIX_CHARS = '-';

/**
 * Python's `re.compile(r'^-\d+$|^-\d*\.\d+$')`, translated with two
 * deliberate details: `\d` is Unicode-aware (so `-١٢` counts as a number), and
 * Python's `$` also matches just before a single trailing newline.
 */
const NEGATIVE_NUMBER_MATCHER = /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;

const isPrefixChar = (ch) => ch !== undefined && PREFIX_CHARS.includes(ch);

/** Code-point aware character access, matching Python's string indexing. */
const charAt = (value, index) => Array.from(value)[index];

/** Code-point aware `value[start:]`. */
const sliceFrom = (value, start) => Array.from(value).slice(start).join('');

/** Code-point aware `value[start:end]`. */
const sliceRange = (value, start, end) => Array.from(value).slice(start, end).join('');

/** `'/'.join(action.option_strings)`, as used in argparse error messages. */
const actionName = (action) => action.names.join('/');

/** Raised for anything that ends in `parser.error(...)`, i.e. exit code 2. */
class ParserError extends Error {}

/** Raised when `-h/--help` fires, i.e. print help and exit 0. */
class HelpRequested extends Error {}

/**
 * @param {{prog: string, usage: string, help: string, actions: Array}} spec
 *   `actions` are `{names, dest, nargs, required}`; `nargs` is 0 for flags and
 *   1 for options taking a single value. Registration order drives both the
 *   "required" message order and abbreviation-ambiguity listings.
 */
export function createParser(spec) {
  const optionActions = new Map();
  for (const action of spec.actions) {
    for (const name of action.names) optionActions.set(name, action);
  }

  /** argparse's `_get_option_tuples`: candidate readings of an unknown flag. */
  function getOptionTuples(argString) {
    const result = [];
    const first = charAt(argString, 0);
    const second = charAt(argString, 1);

    if (isPrefixChar(first) && isPrefixChar(second)) {
      const at = argString.indexOf('=');
      const prefix = at === -1 ? argString : argString.slice(0, at);
      const sep = at === -1 ? null : '=';
      const explicitArg = at === -1 ? null : argString.slice(at + 1);
      for (const [name, action] of optionActions) {
        if (name.startsWith(prefix)) result.push({ action, optionString: name, sep, explicitArg });
      }
    } else if (isPrefixChar(first)) {
      const at = argString.indexOf('=');
      const prefix = at === -1 ? argString : argString.slice(0, at);
      const sep = at === -1 ? null : '=';
      const explicitArg = at === -1 ? null : argString.slice(at + 1);
      const shortPrefix = sliceRange(argString, 0, 2);
      const shortExplicitArg = sliceFrom(argString, 2);
      for (const [name, action] of optionActions) {
        if (name === shortPrefix) {
          result.push({ action, optionString: name, sep: '', explicitArg: shortExplicitArg });
        } else if (name.startsWith(prefix)) {
          result.push({ action, optionString: name, sep, explicitArg });
        }
      }
    }
    return result;
  }

  /**
   * argparse's `_parse_optional`. Returns `null` when the token is a plain
   * value, otherwise the option reading (with `action: null` for an unknown
   * flag, which becomes an "unrecognized argument").
   */
  function parseOptional(argString) {
    if (argString === '') return null;
    if (!isPrefixChar(charAt(argString, 0))) return null;

    const exact = optionActions.get(argString);
    if (exact) return { action: exact, optionString: argString, sep: null, explicitArg: null };

    // A bare '-' is one character long, so argparse treats it as a value.
    if (Array.from(argString).length === 1) return null;

    const at = argString.indexOf('=');
    if (at !== -1) {
      const optionString = argString.slice(0, at);
      const attached = optionActions.get(optionString);
      if (attached) {
        return { action: attached, optionString, sep: '=', explicitArg: argString.slice(at + 1) };
      }
    }

    const tuples = getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map((tuple) => tuple.optionString).join(', ');
      throw new ParserError(`ambiguous option: ${argString} could match ${matches}`);
    }
    if (tuples.length === 1) return tuples[0];

    // Looks like a negative number and no option does, so it is a value.
    if (NEGATIVE_NUMBER_MATCHER.test(argString)) return null;
    // Contains a space, so it was meant to be a value.
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, sep: null, explicitArg: null };
  }

  /**
   * argparse's `_match_argument` for an option action: the nargs pattern has
   * its `-` parts stripped for optionals, so a single-value option needs a
   * value in the very next slot. Returns `null` when nothing matches.
   */
  function matchArgument(action, pattern) {
    if (action.nargs === 0) return 0;
    return pattern[0] === 'A' ? 1 : null;
  }

  /**
   * Parse `argv`, returning `{kind: 'values'|'help', values}` or throwing
   * `ParserError`. Never writes output itself.
   */
  function parseArgs(argv) {
    const optionTuples = new Map();
    const pattern = [];
    for (let i = 0; i < argv.length; i += 1) {
      if (argv[i] === '--') {
        // Everything after the first '--' is a value, including a second '--'.
        pattern.push('-');
        for (let j = i + 1; j < argv.length; j += 1) pattern.push('A');
        break;
      }
      const tuple = parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const values = new Map();
    const seen = new Set();
    const extras = [];

    const takeAction = (action, args, optionString) => {
      seen.add(action);
      if (action.dest === 'help') throw new HelpRequested();
      values.set(action.dest, args[0]);
      void optionString;
    };

    const consumeOptional = (startIndex) => {
      let { action, optionString, sep, explicitArg } = optionTuples.get(startIndex);
      const argString = argv[startIndex];
      const actionTuples = [];
      let stop = startIndex + 1;

      for (;;) {
        if (action === null) {
          extras.push(argString);
          return startIndex + 1;
        }

        if (explicitArg !== null && explicitArg !== undefined) {
          const argCount = matchArgument(action, 'A');
          if (argCount === 0 && !isPrefixChar(charAt(optionString, 1)) && explicitArg !== '') {
            // A single-dash flag with a tail: either an attached '=' value
            // (rejected) or more concatenated short flags to unpack.
            if (sep || isPrefixChar(charAt(explicitArg, 0))) {
              throw new ParserError(
                `argument ${actionName(action)}: ignored explicit argument ${pythonRepr(explicitArg)}`,
              );
            }
            actionTuples.push([action, [], optionString]);
            const prefix = charAt(optionString, 0);
            const nextOptionString = prefix + charAt(explicitArg, 0);
            const nextExplicitArg = sliceFrom(explicitArg, 1) || null;
            const nextAction = optionActions.get(nextOptionString);
            if (nextAction) {
              action = nextAction;
              optionString = nextOptionString;
              explicitArg = nextExplicitArg;
              sep = '';
            } else {
              extras.push(prefix + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ParserError(
              `argument ${actionName(action)}: ignored explicit argument ${pythonRepr(explicitArg)}`,
            );
          }
        } else {
          const start = startIndex + 1;
          const argCount = matchArgument(action, pattern.slice(start).join(''));
          if (argCount === null) {
            throw new ParserError(`argument ${actionName(action)}: expected one argument`);
          }
          stop = start + argCount;
          actionTuples.push([action, argv.slice(start, stop), optionString]);
          break;
        }
      }

      for (const [action_, args, optionString_] of actionTuples) {
        takeAction(action_, args, optionString_);
      }
      return stop;
    };

    // No positional actions are defined, so every value token is an extra.
    const optionIndices = [...optionTuples.keys()].sort((left, right) => left - right);
    const maxOptionIndex = optionIndices.length ? optionIndices[optionIndices.length - 1] : -1;
    let startIndex = 0;
    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = optionIndices.find((index) => index >= startIndex);
      if (startIndex !== nextOptionIndex) {
        extras.push(...argv.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(nextOptionIndex);
    }
    extras.push(...argv.slice(startIndex));

    const missing = spec.actions
      .filter((action) => action.required && !seen.has(action))
      .map(actionName);
    if (missing.length) {
      throw new ParserError(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length) {
      throw new ParserError(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }

  return { parseArgs, spec };
}

export { HelpRequested, ParserError };

