/**
 * The command-line surface of this program: the same two required string
 * options as the Python original, plus argparse's usage and help rendering.
 */

import { HelpRequested, ParserError, createParser } from './argparse.mjs';

/** `os.path.basename(sys.argv[0])`, which is what argparse uses as `prog`. */
function programName(scriptPath) {
  if (!scriptPath) return 'test5.mjs';
  const normalized = scriptPath.replace(/[\\/]+$/, '');
  const cut = Math.max(normalized.lastIndexOf('/'), normalized.lastIndexOf('\\'));
  return cut === -1 ? normalized : normalized.slice(cut + 1);
}

const ACTIONS = [
  { names: ['-h', '--help'], dest: 'help', nargs: 0, required: false },
  { names: ['--a'], dest: 'a', nargs: 1, required: true },
  { names: ['--b'], dest: 'b', nargs: 1, required: true },
];

/**
 * Parse `argv` (the arguments after the script path).
 *
 * Returns `{a, b}` on success. On `-h/--help` it writes the help text to stdout
 * and exits 0; on any parse error it writes the usage line plus the error to
 * stderr and exits 2 — exactly as argparse does.
 */
export function parseCommandLine(argv, scriptPath) {
  const prog = programName(scriptPath);
  const usage = `usage: ${prog} [-h] --a A --b B`;
  const help = [
    usage,
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '',
  ].join('\n');

  const parser = createParser({ prog, usage, help, actions: ACTIONS });
  try {
    const values = parser.parseArgs(argv);
    return { a: values.get('a'), b: values.get('b') };
  } catch (error) {
    if (error instanceof HelpRequested) {
      process.stdout.write(help);
      process.exit(0);
    }
    if (error instanceof ParserError) {
      process.stderr.write(`${usage}\n${prog}: error: ${error.message}\n`);
      process.exit(2);
    }
    throw error;
  }
}

