/**
 * Differential harness: runs the Python executable and a Node port over a large
 * corpus and compares stdout/stderr/exit-code byte for byte.
 *
 * Usage: node diff.mjs <path-to-test5.mjs> [--verbose]
 */
import { execFileSync } from 'node:child_process';
import { bech32Encode } from '/tmp/mine/lib/bech32.mjs';
import { convertBits } from '/tmp/mine/lib/convertbits.mjs';

const EXE = '/workspace/dataset/test5_executable';
const TARGET = process.argv[2];
const VERBOSE = process.argv.includes('--verbose');

function run(cmd, args, argv) {
  const out = { stdout: '', stderr: '', rc: 0 };
  try {
    out.stdout = execFileSync(cmd, args.concat(argv), { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) {
    out.rc = e.status === null ? -1 : e.status;
    out.stdout = e.stdout === null ? '' : String(e.stdout);
    out.stderr = e.stderr === null ? '' : String(e.stderr);
  }
  return out;
}

const seg = (hrp, ver, prog) => bech32Encode(hrp, [ver].concat(convertBits(prog, 8, 5, true)));
const bytesOf = (n, seed) => Array.from({ length: n }, (_, i) => (i * 37 + seed * 11 + 7) & 255);

// ---------------------------------------------------------------- corpus ----
const cases = [];
