// 1. sample cases from the original task description
add(['--a', 'xyz', '--b', 'xyz1s5y9ce53aq686ffxxxjk6scl7zt3efeze40r73h']);
add(['--a', 'xyz', '--b', 'xyz1k5lu9cjaf246ey924w55j3e3uhu62tpg0s']);
add(['--a', 'ltc', '--b', 'ltc1hsja87ry7v8cn6rfgv46af5t9l4t5rqu3d2']);
add(['--a', 'tltc', '--b', 'tltc13mckasdanexqhjnx7y4353snvf0re5gplj']);
add(['--a', 'bc', '--b', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4']);
add(['--a', 'bc', '--b', 'bc1pmfr3p9j00pfxjh0zmgp99y8zftmd3s5pmedqhyptwy6lm87hf5sspknck9']);
add(['--a', 'tb', '--b', 'tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3q0sl5k7']);

