for (const hrp of HRPS) {
  for (const ver of [0, 1, 2, 15, 16, 17, 31]) {
    for (const len of [0, 1, 2, 3, 19, 20, 21, 31, 32, 33, 39, 40, 41]) {
      const addr = seg(hrp, ver, bytesOf(len, ver));
      add(['--a', hrp, '--b', addr]);
      add(['--a', hrp, '--b', addr.toUpperCase()]);
      add(['--a', hrp.toUpperCase(), '--b', addr.toUpperCase()]);
