  const c = ALPHA[(i * 7) % ALPHA.length];
  add(['--a', 'bc', '--b', BASE.slice(0, i) + c + BASE.slice(i + 1)]);
  add(['--a', 'bc', '--b', BASE.slice(0, i) + BASE.slice(i + 1)]);
  add(['--a', 'bc', '--b', BASE.slice(0, i) + c + BASE.slice(i)]);
  if (i + 2 <= BASE.length) add(['--a', 'bc', '--b', BASE.slice(0, i) + BASE[i + 1] + BASE[i] + BASE.slice(i + 2)]);
  add(['--a', 'bc', '--b', BASE.slice(0, i) + BASE[i].toUpperCase() + BASE.slice(i + 1)]);
}

// 4. structural edges
for (const b of ['', '1', '11', '111', 'bc', 'bc1', 'bc1q', 'bc1qqqqq', 'bc1qqqqqq', 'bc1qqqqqqq',
  '1' + BASE, BASE + '1', BASE.replace('1', '11'), 'a1b' + BASE.slice(2), 'q'.repeat(90),
  'q'.repeat(91), 'bc1' + 'q'.repeat(200), bech32Encode('bc', []), bech32Encode('bc', [0]),
  bech32Encode('bc', [0, 0]), bech32Encode('bc', [1, 0]), bech32Encode('', [0]), bech32Encode('a1b', [0, 1, 2])]) {
  for (const a of ['bc', '', 'a1b', 'a', 'BC', 'x']) add(['--a', a, '--b', b]);
