// 5. pad=false boundary: append extra data chars to an exact-fit payload
{
  const exact = [1].concat(Array.from({ length: 32 }, (_, i) => (i * 5) % 32));
  for (const extra of [[], [0], [31], [0, 0], [0, 1], [1, 0], [0, 0, 0], [16], [8], [4], [2], [1]]) {
    add(['--a', 'bc', '--b', bech32Encode('bc', exact.concat(extra))]);
