  ['--a=bc', '--b=' + G], ['--a=', '--b='], ['--a=bc', '--b', G], ['--a', 'bc', '--b=' + G],
  ['--b', G, '--a', 'bc'], ['--a', 'bc', '--a', 'tb', '--b', G], ['--b', 'x', '--b', G, '--a', 'bc'],
  ['--c', 'y'], ['--a', 'bc', '--c', 'y'], ['--a', 'bc', '--b', G, '--c', 'y'],
  ['foo'], ['foo', 'bar'], ['--a', 'bc', '--b', G, 'foo'], ['--a', 'bc', '--b', G, 'foo', 'bar'],
  ['foo', '--a', 'bc', '--b', G], ['--a', 'bc', 'foo', '--b', G], ['--a', 'bc', '--b', G, 'foo', '--c'],
  ['--c', '--a', 'bc', '--b', G], ['-a', 'bc', '-b', 'x'], ['-a'], ['-b'], ['-x'], ['-x', '--a', 'bc', '--b', G],
  ['--A', 'bc', '--B', 'x'], ['--ab', 'x'], ['--ab', 'x', '--a', 'bc', '--b', G],
  ['---a', 'x'], ['---', 'x', '--a', 'bc', '--b', G], ['-', 'x', '--a', 'bc', '--b', G],
  ['--=x'], ['--='], ['--=x', '--a', 'bc', '--b', G], ['--'], ['--', 'x'],
  ['--a', 'bc', '--b', '--', 'x'], ['--a', 'bc', '--', '--b', G], ['--a', 'bc', '--b', G, '--'],
  ['--a', 'bc', '--b', G, '--', 'z'], ['--', '--a', 'bc'], ['--', '--a', 'bc', '--b', G],
  ['--help'], ['-h'], ['--h'], ['--he'], ['--hel'], ['--a', 'bc', '--help'], ['--help', '--a'],
  ['--help', '=x'], ['--help=x'], ['-h=x'], ['-hx'], ['-h', '-h'], ['-h', '--a'],
  ['--help=abc'], ["--help=a'b"], ['--help=a"b'], ['--help=a\nb'], ['--help=\t'], ['--help=é'],
  ['--help=-x'], ['--help=--'], ['-h-x'], ['-h', 'foo'],
  ['--a', '--b'], ['--a', '--b', '--b', 'x'], ['--a=--b', '--b=x'], ['--a', 'bc', '--b', '--b'],
  ['--a', 'bc', '--b', '-'], ['--a', 'bc', '--b', '-1'], ['--a', 'bc', '--b', '-1.5'],
  ['--a', 'bc', '--b', '-.5'], ['--a', 'bc', '--b', '-0'], ['--a', 'bc', '--b', '-x'],
  ['--a', 'bc', '--b', '-1e5'], ['--a', 'bc', '--b', '-1x'], ['--a', 'bc', '--b', '+1'],
  ['--a', 'bc', '--b', '- '], ['--a', 'bc', '--b', '-1 '], ['--a', 'bc', '--b', '-1\n'],
  ['--a', 'bc', '--b', '-1\n\n'], ['--a', 'bc', '--b', '-1\r'], ['--a', 'bc', '--b', '-١٢'],
  ['--a', 'bc', '--b', '-١٢\n'], ['--a', 'bc', '--b', '-①'], ['--a', 'bc', '--b', '-¹'],
  ['--a', 'bc', '--b', '-\u{1F600}'], ['--a', '-1', '--b', G], ['--a', '-x', '--b', G],
  ['--a', 'bc', '--b=-x'], ['--a', 'bc', '--b=--'], ['--a', 'bc', '--b=-'],
  ['--a', 'b=c', '--b', 'x=y'], ['--a', 'bc', '--b', 'a b'], ['--a', 'bc', '--b', 'a\nb'],
  ['--a', 'bc', '--b', G, '--b'], ['--b', '--a'], ['--a', 'bc', '--b', G, '--a'],
]) add(argv);

// 9. randomized fuzz over a deterministic LCG
let state = 20260807;
const rnd = (n) => { state = (state * 1103515245 + 12345) & 0x7fffffff; return state % n; };
const FUZZ_ALPHA = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l1biozZQ-.=_ #~\t\néΩ';
for (let i = 0; i < 400; i += 1) {
  const len = rnd(50);
  let s = '';
  for (let j = 0; j < len; j += 1) s += FUZZ_ALPHA[rnd(FUZZ_ALPHA.length)];
  add(['--a', ['bc', 'tb', 'xyz', '', 'q'][rnd(5)], '--b', s]);
}

// ---------------------------------------------------------------- compare ----
let mismatches = 0;
const norm = (s) => s.split('test5_executable').join('§PROG§').split('test5.mjs').join('§PROG§');
for (const argv of cases) {
  const expected = run(EXE, [], argv);
  const actual = run(process.execPath, [TARGET], argv);
  const same = norm(expected.stdout) === norm(actual.stdout)
    && norm(expected.stderr) === norm(actual.stderr)
    && expected.rc === actual.rc;
  if (!same) {
    mismatches += 1;
    if (mismatches <= 25) {
      console.log('MISMATCH argv=' + JSON.stringify(argv));
      console.log('   py  rc=' + expected.rc + ' out=' + JSON.stringify(expected.stdout) + ' err=' + JSON.stringify(expected.stderr));
      console.log('   js  rc=' + actual.rc + ' out=' + JSON.stringify(actual.stdout) + ' err=' + JSON.stringify(actual.stderr));
    }
  } else if (VERBOSE) {
    console.log('ok ' + JSON.stringify(argv).slice(0, 90));
  }
}
console.log(`\n${cases.length} cases, ${mismatches} mismatches`);
process.exit(mismatches ? 1 : 0);

