// 2. witness version x program length matrix, several HRPs, both cases
const HRPS = ['bc', 'tb', 'ltc', 'tltc', 'xyz', 'a', 'bcrt', 'a'.repeat(30), 'a'.repeat(82), 'a'.repeat(83), 'a'.repeat(84), 'a'.repeat(85)];
for (const hrp of HRPS) {
  for (const ver of [0, 1, 2, 15, 16, 17, 31]) {
    for (const len of [0, 1, 2, 3, 19, 20, 21, 31, 32, 33, 39, 40, 41]) {
      const addr = seg(hrp, ver, bytesOf(len, ver));
      add(['--a', hrp, '--b', addr]);
      add(['--a', hrp, '--b', addr.toUpperCase()]);
      add(['--a', hrp.toUpperCase(), '--b', addr.toUpperCase()]);
    }
  }
}

// 3. mutations of a valid address: substitute / delete / insert / transpose / recase
const BASE = seg('bc', 0, bytesOf(20, 3));
const ALPHA = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l1bioBIO!~ -=@';
for (let i = 0; i < BASE.length; i += 1) {
  const c = ALPHA[(i * 7) % ALPHA.length];
  add(['--a', 'bc', '--b', BASE.slice(0, i) + c + BASE.slice(i + 1)]);
  add(['--a', 'bc', '--b', BASE.slice(0, i) + BASE.slice(i + 1)]);
  add(['--a', 'bc', '--b', BASE.slice(0, i) + c + BASE.slice(i)]);
  if (i + 2 <= BASE.length) add(['--a', 'bc', '--b', BASE.slice(0, i) + BASE[i + 1] + BASE[i] + BASE.slice(i + 2)]);
  add(['--a', 'bc', '--b', BASE.slice(0, i) + BASE[i].toUpperCase() + BASE.slice(i + 1)]);
}

// 4. structural edges
for (const b of ['', '1', '11', '111', 'bc', 'bc1', 'bc1q', 'bc1qqqqq', 'bc1qqqqqq', 'bc1qqqqqqq',
  '1' + BASE, BASE + '1', BASE.replace('1', '11'), 'a1b' + BASE.slice(2), 'q'.repeat(90),
  'q'.repeat(91), 'bc1' + 'q'.repeat(200), bech32Encode('bc', []), bech32Encode('bc', [0]),
  bech32Encode('bc', [0, 0]), bech32Encode('bc', [1, 0]), bech32Encode('', [0]), bech32Encode('a1b', [0, 1, 2])]) {
  for (const a of ['bc', '', 'a1b', 'a', 'BC', 'x']) add(['--a', a, '--b', b]);
}

// 5. pad=false boundary: append extra data chars to an exact-fit payload
{
  const exact = [1].concat(Array.from({ length: 32 }, (_, i) => (i * 5) % 32));
  for (const extra of [[], [0], [31], [0, 0], [0, 1], [1, 0], [0, 0, 0], [16], [8], [4], [2], [1]]) {
    add(['--a', 'bc', '--b', bech32Encode('bc', exact.concat(extra))]);
  }
}

// 6. non-ASCII / control characters
const ODD = [' ', '\t', '\n', '\r', '\v', '\f', '\0', String.fromCharCode(0x7f), String.fromCharCode(0x1f),
  String.fromCharCode(0x80), 'é', 'Ω', '\u{1F600}', 'ı', 'K', 'ſ', '�', '１', 'İ', 'ß', ' '];
for (const ch of ODD) {
  add(['--a', 'bc', '--b', ch + BASE]);
  add(['--a', 'bc', '--b', BASE + ch]);
  add(['--a', 'bc', '--b', BASE.slice(0, 5) + ch + BASE.slice(5)]);
  add(['--a', 'bc' + ch, '--b', BASE]);
  add(['--a', ch, '--b', BASE]);
}

// 7. HRP mismatch matrix
for (const a of ['bc', 'BC', 'Bc', 'b', 'bcc', '', 'bc1', 'tb', 'a'.repeat(84), 'bc ']) {
  add(['--a', a, '--b', BASE]);
  add(['--a', a, '--b', BASE.toUpperCase()]);
}

// 8. argparse matrix
const G = 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4';
for (const argv of [
  [], ['--a', 'bc'], ['--b', G], ['--a'], ['--b'], ['--a', 'bc', '--b'],
  ['--a=bc', '--b=' + G], ['--a=', '--b='], ['--a=bc', '--b', G], ['--a', 'bc', '--b=' + G],
  ['--b', G, '--a', 'bc'], ['--a', 'bc', '--a', 'tb', '--b', G], ['--b', 'x', '--b', G, '--a', 'bc'],
  ['--c', 'y'], ['--a', 'bc', '--c', 'y'], ['--a', 'bc', '--b', G, '--c', 'y'],
  ['foo'], ['foo', 'bar'], ['--a', 'bc', '--b', G, 'foo'], ['--a', 'bc', '--b', G, 'foo', 'bar'],
  ['foo', '--a', 'bc', '--b', G], ['--a', 'bc', 'foo', '--b', G], ['--a', 'bc', '--b', G, 'foo', '--c'],
  ['--c', '--a', 'bc', '--b', G], ['-a', 'bc', '-b', 'x'], ['-a'], ['-b'], ['-x'], ['-x', '--a', 'bc', '--b', G],
  ['--A', 'bc', '--B', 'x'], ['--ab', 'x'], ['--ab', 'x', '--a', 'bc', '--b', G],
  ['---a', 'x'], ['---', 'x', '--a', 'bc', '--b', G], ['-', 'x', '--a', 'bc', '--b', G],
  ['--=x'], ['--='], ['--=x', '--a', 'bc', '--b', G], ['--'], ['--', 'x'],
  ['--a', 'bc', '--b', '--', 'x'], ['--a', 'bc', '--', '--b', G], ['--a', 'bc', '--b', G, '--'],
  ['--a', 'bc', '--b', G, '--', 'z'], ['--', '--a', 'bc'], ['--', '--a', 'bc', '--b', G],
  ['--help'], ['-h'], ['--h'], ['--he'], ['--hel'], ['--a', 'bc', '--help'], ['--help', '--a'],
  ['--help', '=x'], ['--help=x'], ['-h=x'], ['-hx'], ['-h', '-h'], ['-h', '--a'],
  ['--help=abc'], ["--help=a'b"], ['--help=a"b'], ['--help=a\nb'], ['--help=\t'], ['--help=é'],
  ['--help=-x'], ['--help=--'], ['-h-x'], ['-h', 'foo'],
  ['--a', '--b'], ['--a', '--b', '--b', 'x'], ['--a=--b', '--b=x'], ['--a', 'bc', '--b', '--b'],
  ['--a', 'bc', '--b', '-'], ['--a', 'bc', '--b', '-1'], ['--a', 'bc', '--b', '-1.5'],
  ['--a', 'bc', '--b', '-.5'], ['--a', 'bc', '--b', '-0'], ['--a', 'bc', '--b', '-x'],
  ['--a', 'bc', '--b', '-1e5'], ['--a', 'bc', '--b', '-1x'], ['--a', 'bc', '--b', '+1'],
  ['--a', 'bc', '--b', '- '], ['--a', 'bc', '--b', '-1 '], ['--a', 'bc', '--b', '-1\n'],
  ['--a', 'bc', '--b', '-1\n\n'], ['--a', 'bc', '--b', '-1\r'], ['--a', 'bc', '--b', '-١٢'],
  ['--a', 'bc', '--b', '-١٢\n'], ['--a', 'bc', '--b', '-①'], ['--a', 'bc', '--b', '-¹'],
  ['--a', 'bc', '--b', '-\u{1F600}'], ['--a', '-1', '--b', G], ['--a', '-x', '--b', G],
  ['--a', 'bc', '--b=-x'], ['--a', 'bc', '--b=--'], ['--a', 'bc', '--b=-'],
  ['--a', 'b=c', '--b', 'x=y'], ['--a', 'bc', '--b', 'a b'], ['--a', 'bc', '--b', 'a\nb'],
  ['--a', 'bc', '--b', G, '--b'], ['--b', '--a'], ['--a', 'bc', '--b', G, '--a'],
]) add(argv);

// 9. randomized fuzz over a deterministic LCG
let state = 20260807;
const rnd = (n) => { state = (state * 1103515245 + 12345) & 0x7fffffff; return state % n; };
const FUZZ_ALPHA = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l1biozZQ-.=_ #~\t\néΩ';
for (let i = 0; i < 400; i += 1) {
  const len = rnd(50);
  let s = '';
  for (let j = 0; j < len; j += 1) s += FUZZ_ALPHA[rnd(FUZZ_ALPHA.length)];
  add(['--a', ['bc', 'tb', 'xyz', '', 'q'][rnd(5)], '--b', s]);
}

// ---------------------------------------------------------------- compare ----
let mismatches = 0;
const norm = (s) => s.split('test5_executable').join('§PROG§').split('test5.mjs').join('§PROG§');
for (const argv of cases) {
  const expected = run(EXE, [], argv);
  const actual = run(process.execPath, [TARGET], argv);
  const same = norm(expected.stdout) === norm(actual.stdout)
    && norm(expected.stderr) === norm(actual.stderr)
    && expected.rc === actual.rc;
  if (!same) {
    mismatches += 1;
    if (mismatches <= 25) {
      console.log('MISMATCH argv=' + JSON.stringify(argv));
      console.log('   py  rc=' + expected.rc + ' out=' + JSON.stringify(expected.stdout) + ' err=' + JSON.stringify(expected.stderr));
      console.log('   js  rc=' + actual.rc + ' out=' + JSON.stringify(actual.stdout) + ' err=' + JSON.stringify(actual.stderr));
    }
  } else if (VERBOSE) {
    console.log('ok ' + JSON.stringify(argv).slice(0, 90));
  }
}
console.log(`\n${cases.length} cases, ${mismatches} mismatches`);
process.exit(mismatches ? 1 : 0);
